def find_minimum_lines(N, M):
    # Count the frequency of each piece number
    piece_count = {}
    for a, b in M:
        if a in piece_count:
            piece_count[a] += 1
        else:
            piece_count[a] = 1
        if b in piece_count:
            piece_count[b] += 1
        else:
            piece_count[b] = 1

    # Initialize the DP table
    dp = [float('inf')] * (N + 1)
    dp[0] = 0  # Base case

    # Fill the DP table
    for piece in range(1, N + 1):
        if piece not in piece_count:
            dp[piece] = piece_count[0] * 2 + 1  # Minimum lines required for this piece alone
        else:
            dp[piece] = min(dp[piece - count] + count * 2 + piece_count[piece] * 3 for count in piece_count[piece] if piece_count[piece] > count and piece != 1 and piece != N)

    return dp[N]

