from collections import deque

def solve(join_events, cancel_events, query_times):
    join_times, visit_lengths = {}, {}
    for i, event in enumerate(join_events):
        join_time, duration = event.split()
        join_times[i + 1] = int(join_time)
        visit_lengths[i + 1] = int(duration)
    for event in cancel_events:
        cancel_index = int(event)
        if cancel_index in join_times:
            del join_times[cancel_index]
    queue = deque()
    queue_times = {}
    current_visit = None
    waiting_time = []
    for index in sorted(join_times.keys()):
        wait_time = 0
        while queue_times[len(queue)] == current_visit:
            current_visit += visit_lengths[len(queue) + 1]
            wait_time += 1
            if len(queue) == 0:
                break
        last_index_sorted = len(queue_times.keys()) - 1
        if current_visit - 1 in queue_times and current_visit - 1 in join_times:
            if join_times.index(current_visit - 1) < join_times.index(queue_times[last_index_sorted][-1]):
                last_index_sorted = join_times.index(current_visit - 1) + 1
        for i in range(last_index_sorted):
            wait_time += queue_times[len(queue)][i + 1]
            num_que = i + 1 + len(queue)
            lead_index = queue_times[num_que][-1]
            while (
                lead_index == -1
                or join_times[lead_index] <= join_times[num_que]
                and current_visit - 1 <= join_times[lead_index]
            ):
                lead_index = queue_times[num_que][i]
                if queue_times[num_que][i + 1] < len(queue) + 1:
                    break
        if len(queue) > 0:
            wait_time += queue_times[len(queue)][1]
            current_visit += visit_lengths[len(queue) + 1]

        queue += deque([(join_times[index], len(queue) + 1, current_visit + wait_time)])
        if index in join_times and index in visit_lengths:
            queue_times[index] = deque(
                [
                    [len(queue) + 1, current_visit + wait_time],
                ]
            )
        else:
            queue_times[index] = deque()
        waiting_time.append(wait_time)
    return waiting_time

# Example usage
join_events = ["+ 2 2", "+ 5 2", "+ 1 2", "join 3", "- 3", "join 2", "+ 5 2", "join 7", "? 2", "? 5"]
cancel_events = ["cancel 6", "join 3", "join 1"]
query_times = ["? 2", "? 5"]
print(solve(join_events, cancel_events, query_times))
