import sys

class Queue:
    def __init__(self):
        self.arrival_times = []
        self.visit_durations = []
        self.event_queue = []

    def add_visit(self, time, duration):
        self.arrival_times.append(time)
        self.visit_durations.append(duration)

    def process_events(self, event):
        if event.isdigit():
            i = int(event) - 1
            if i < len(self.arrival_times):
                self.arrival_times[i] = self.arrival_times[i] - self.visit_durations[i]
            elif i > len(self.arrival_times):
                self.visit_durations[i - len(self.arrival_times)] = self.visit_durations[i]
        else:
            self.arrival_times.remove(self.arrival_times[int(event)])
            del self.visit_durations[int(event)]

    def get_wait_time(self, query_time):
        for i in range(len(self.arrival_times)):
            if self.arrival_times[i] <= query_time:
                if self.arrival_times[i] < query_time and (self.visit_durations[i] == 0 or self.arrival_times[i] == 2):
                    wait_time = self.arrival_times[i] - query_time
                elif self.arrival_times[i] >= query_time:
                    wait_time = (self.arrival_times[i] - 2) - query_time
                    self.arrival_times[i] = 2
                    if self.visit_durations[i] != 0:
                        self.process_events(str(self.arrival_times[i] + self.visit_durations[i]) + ' ' + str(self.visit_durations[i]))
                    else:
                        self.arrival_times.pop(i)
                        self.visit_durations.pop(i)
        return wait_time

def main():
    q = int(input())
    queue = Queue()
    for _ in range(q):
        event = input().strip()
        if event.startswith('+'):
            data = event.split()
            time, duration = int(data[2]), int(data[3])
            queue.add_visit(time, duration)
        elif event.startswith('-'):
            data = event.split()
            index = int(data[1]) - 1
            queue.process_events(str(index + 1))
        elif event.startswith('?'):
            data = event.split()
            query_time = int(data[1])
            wait_time = queue.get_wait_time(query_time)
            print(wait_time)

if __name__ == "__main__":
    main()
