import sys

def findCycle(u, visited, parent):
    visited[u] = True
    for v in adj_list[u]:
        if not visited[v]:
            parent[v] = u
            if cycleFound == (parent[v] == u):
                return v
            return findCycle(v, visited, parent)
        elif v != parent[u]:
            return None
    return False

def bridges(edges):

    def findEdges(u, visited, parent, stack, bridges):
        visited[u] = True
        for v in adj_list[u]:
            if not visited[v]:
                parent[v] = u
                root = findEdges(v, visited, parent, stack, bridges)
                if root is not None:
                    return root if stack.pop() == u else None
            elif v != parent[u] and root is not None and root not in stack:
                # u-v is a bridge, hence a bridge edge
                edges.add((u, v))
                bridges.append(root)
        return u

    cycleFound = False
    global adj_list
    adj_list = [[] for _ in range(N - 1)]
    parent = [None for _ in range(N - 1)]
    cycle = findCycle(0, [False] * N, parent)

    if cycle is not None:
        cycleFound = True
        findEdges(cycle, [False] * N, parent, collections.deque([cycle]), edges)

    if cycleFound:
        return list(edges)
    else:
        return []

def findMapping(edges):

    buses = [Edge(0, False, None)] + sorted(edges, key=lambda x: x.vertex2, reverse=True)
    trains = bridges(edges)

    D, buses, trains = dict((u, (d := buses.index((u, False, None))))), [], []
    for e in trains:
        if len(trains) - buses[D[e.vertex2] if D[e.vertex2] != -1 else 0] > D[e.vertex2] - D[e.vertex1]:
            D[e.vertex2] += 1
            buses.append((D[e.vertex2], e, trains.pop()))
        elif len(trains) - buses[D[e.vertex1] if D[e.vertex1] != -1 else 0] > e.vertex2 - D[e.vertex1]:
            D[e.vertex1] += 1
            buses.append((D[e.vertex1], e, trains.pop()))
    return [buses[i][0] for i in ancestors(buses)]

def ancestors(edges, zeroVertex = 0):

    def _ancestors(u, parent):
        chain = set([u])
        for v, e, _ in edges:
            if v == parent:
                continue
            if e.vertex1 == u:
                chain |= _ancestors(v, u)
            if e.vertex2 == u:
                chain |= _ancestors(v, u)
        return chain

    return _ancestors(zeroVertex, zeroVertex)

