def find(f: List[int], x: int) -> int:
    if f[x] < 0:
        return x
    f[x] = find(f, f[x])
    return f[x]

def union(f: List[int], x: int, y: int) -> bool:
    rx, ry = find(f, x), find(f, y)
    if rx == ry:
        return False
    if f[rx] > f[ry]:
        f[rx], f[ry] = f[ry], f[rx]
    f[rx] += f[ry]
    f[ry] = rx
    return True
    return True

def kruskal(mst: List[int], compcnt: int, edges: List[List[int]], g: defaultdict[int, List[int]], cnt: int, k: int) -> bool:
    if cnt == compcnt:
        return True
    for i in range(cnt):
        for j in g.keys():
            if i == find(compcnt, j) and depth[i] + depth[find(compcnt, j)] <= k:
                for y in range(len(edges[i])):
                    if edges[i][y] != -1 and compcnt[find(compcnt, edges[i][y])] != -1:
                        merge(find(compcnt, i), find(compcnt, edges[i][y]))
                        edges[i][y] = -1
    return not kruskal(mst, compcnt, edges, g, cnt + 1, k)

