import sys

class QueueNode:
    def __init__(self, time, duration):
        self.time = time
        self.duration = duration
        self.next = None

def add_to_queue(queue, time, duration):
    new_node = QueueNode(time, duration)
    current = queue
    if current:
        while current.next:
            current = current.next
        current.next = new_node
    else:
        queue = new_node

def remove_from_queue(queue, time, key):
    if not queue:
        return None
    else:
        current = queue
        last_element = None
        while current:
            if current.time == key:
                if not last_element:
                    queue = current.next
                else:
                    last_element.next = current.next
                return current.duration
            last_element = current
            current = current.next
        return None

def query_time(queue, query_time):
    knight = remove_from_queue(queue, query_time, 0)
    if knight:
        return knight.duration
    else:
        return 0

