def min_lines(N, relations):
    # Initialize a graph to represent the relationships
    graph = {i: [] for i in range(1, N + 1)}

    # Build the graph based on the relationships
    for a, b in relations:
        if a <= b:
            graph[a].append(b)
            graph[b].append(a)
        else:
            graph[a].append(b)
            graph[b].append(a)

    # Find the maximum number of nodes reachable from a single node
    def dfs(node, visited):
        count = 0
        for neighbor in graph[node]:
            if neighbor not in visited:
                count += dfs(neighbor, visited | {neighbor})
        return count

    max_reachable = 0
    for i in range(1, N + 1):
        if dfs(i, {i}) >= N / 2:
            max_reachable = N if max_reachable == N else max(max_reachable, N - dfs(i, {i}))

    return max(reversed(graph), default=lambda: [0])(0) + (N - max_reachable)

