    row_sums = [0] * (n + 1)
    for i in range(n):
        for j in range(n):
            if j > 0: row_sums[i] += dimensions_matrix[j-1][i]
        row_counts = [0] * (n + 1 - row_sums[i])
        for j in range(n):
            row_counts[row_sums[i] - row_sums[j]] += 1
        max_row_count = max(row_counts)

        col_sums = [0] * n
        for j in range(n):
            col_sums[j] += dimensions_matrix[j][i-count_row_sums[0][j]]
        col_counts = [0] * (n + 1 - col_sums[j])
        for j in range(n):
            col_counts[col_sums[j] - col_sums[j-1]] += 1
        max_col_count = max(col_counts)

        if max_row_count * max_col_count <= 0:
