def max_non_intersecting_rectangles(dimensions_matrix):
    dimensions = [0] * len(dimensions_matrix[0])
    for i in range(len(dimensions_matrix)):
        for j in range(len(dimensions_matrix[0])):
            if dimensions[j] == 0:
                dimensions[j] = (dimensions_matrix[i][j], i, j)
    dimensions.sort()

    min_points, max_points = {}, {}
    for i in range(len(dimensions)):
        if dimensions[i][1] not in max_points:
            max_points[dimensions[i][1]] = []
        max_points[dimensions[i][1]].append(dimensions[i])
        if dimensions[i][2] not in min_points:
            min_points[dimensions[i][2]] = []
        min_points[dimensions[i][2]].append(dimensions[i])

    values = set([sum(dimensions[i][0:2]) for i in dimensions])
    values.add(0)
    max_iterations = 1 + min(len(max_points), len(min_points))
    ans = 0

    for area in values:
        values2 = set([])
        max_area = 0
        for part in range(0, max_iterations+1):
            if part in min_points:
                points = min_points[part]
            else:
                points = []

            for last_part in range(part, max_iterations+1):
                if last_part in max_points:
                    points = points.union(set(max_points[last_part]))

            for part_i in points:
                if part_i[0] in values2 or part_i[1] in values2:
                    continue
                values2.add(part_i[0])
                if area - part_i[0] in min_points.keys():
                    for last_part in range(part_i[0] + area, max_iterations+1, area):
                        if last_part in min_points.keys():
                            cache_intersections = set([min_points[last_part],])
                        else:
                            cache_intersections = set([])
                        for last_loop in max_points[part_i[1]:last_part-1]:
                            intersections = max_points[part_i[1]:last_part-1].union(cache_intersections)
                            for first_part in cache_intersections:
                                intersections = intersections.union(max_points[first_part[1] - area:last_part - 1])
                            for intersection in intersections:
                                values2.add(max_points[intersection][0])
                                max_area = max(max_area, len(cache_intersections) + len(intersections))
                                last_loop = max_points[intersection]
                                break

        ans = max(ans, max_area)
    return ans

