#!/usr/bin/env python3
# encoding: utf-8

"""
    Qwen, Your helpful assistant on coding, sciences, and everything between.
    Created by Yidel.

    Given the input two grid lines, output the maximum count of non-overlapping nice rectangles.
"""

from typing import List

def is_nice(grid: List[List[int]], i1: int, j1: int, i2: int, j2: int) -> bool:
    """
    A rectangle at (i1,j1) and (i2,j2) is nice if the sum of the elements in the rectangle is equal to 0.
    """
    return sum(grid[i1][j1: j2]) + sum(grid[i2][j1: j2]) + sum(grid[i1: i2][j1]) + sum(grid[i1: i2][j2]) == 0

def dfs(n: int, grid: List[List[int]], rowMap: 'List[List[bool]]') -> int:
    """ O(N + N * M * dM) + O(N * M), N^2 on bad case.
        This is O((N * M)^3) over entire input, which is bad.
    """
    if n <= 0 or n == 3**m:
        return n
    ans = 0
    for i in range(3):
        for j in range(3):
            for k in range(3):
                if not rowMap[i][j][k]:  # Vertical Check
                    if grid[0][j] + grid[2][j] == 0 and grid[0][k] + grid[2][k] == 0:
                        x1, x2, y1, y2 = 0, 3**m//3**3//3**m-3**m//3**3//3**m-1, 0, 3**m//3**3//3**m-3**m//3**3//3**m-1
                        if j == k:  # Same row / if column
                            x1, x2 = 0, 3**m//3**3//3**m-1  # Start at the top left cell
                            while y1 <= y2:
                                if is_nice(grid, x1, y1, x2, y2):
                                    ans = max(ans, 2)
                                else:
                                    x1 += 1
                                    x2 += 1
                                    y1 += 1
                                    y2 += 1
                        else:  # Different rows / if columns
                            for xi in range(x1, x2+1):
                                for yi in range(y1, y2+1):
                                    if is_nice(grid, xi, yi, xi, yi):
                                        ans = max(ans, 2)
                rowMap[i][j][k] = True
    return ans + dfs(n-1, grid, rowMap)

def can_progress(grid: List[List[int]], n: int) -> bool:
    rowMap = [[False]*3, *[False]*3]*3
    for i in range(n):
        if not is_nice(grid, 0, i, 2, i):
            return False
    return dfs(min(n, n), grid, rowMap) == n

def solve(n: int) -> int:
    global rowMap
    n = min(n, min(3**m, n))
    rowMap = [[False]*3]*3
    while not can_progress(rowMap, n):
        rowMap[0][1] = True
        rowMap[1][0] = True
        rowMap[2][2] = True
        zero_array = [[rowMap[i][0], rowMap[i][1], rowMap[i][2]] for i in range(3)]
        for i in range(3):
            for j in range(3):
                for k in range(3):
                    if rowMap[i][j][k]:
                        for zr in zero_array:
                            zi = zr[i]
                            if zi == 0 and j == 0: w1 = False
                            elif zi == 0 and j == 1: w2 = False
                            elif zi != 0 and j == 0: w1 = zi != 0
                            elif ki == 0: w2 = zi != 0
                            elif j == 1: w2 = zi != 0
                            elif j == 2: w2 = zi != 0
                            if None in (w1, w2): continue
                            if not (zr[i] + zi == 0): continue
                            if zr[i] > zi: continue
                            if (zr[2] + zi) != 0: continue
                            ans = new_ans(zr, zi, i, j, k)
                            best = rowMap
                            if ans > 0 and ans < best[0][0].get(min(i, k), -1) and ans == best[0][1].get(min(i, k), -1):  # cannot compare norm
                                best[0][2] = zi
                                best[0][1] = zr
                                best[0][0] = zi + zr
                                best[0][0].sort()
                                best[0].sort()
                                ans = min(ans, best[0][0])
                            elif ans > 1e-5 and best[0][1][0].get(min(i, k), -1) and ans == best[1][0][min(i, k)]:  # signed
                                best[1][1] = zr
                                best[1][0] = zi
                                best[0][1] = zr
                                best[1][2] = zi + zr
                                best[1][0][0] = (best[1][0][0] + zi) if len(zi) > 1 else ans
                                ans = min(ans, best[1][0][0])
                            if ans > 0 or ans < best[0][0].get(min(i, k), -1):  # not bad case
                                rowMap[i][j][k] = True
    return round(sum([zi[0] for zi in rowMap]))

def new_ans(zr: List[int], zi: int, i: int, j: int, k: int) -> int:
    # Since the only nice rectangles are on the diagonal filled with negative numbers (except the corner cells)
    if zi == 0: return int(zr[i]**2/4)
    return int((2-zi**2+zi*(4-i-j))**0.5)

if __name__ == '__main__':
    m = int(input())
    q = int(input())
    rowTricks = [0]*m
    for _ in range(q):
        inputs = list(map(int, input().split()))
        i, j = min(inputs) if m == 1 else min(inputs)//3, inputs[1]//3
        rowTricks[i] += 1
        if j: rowTricks[Math.Max(i + j - 1, 0)] -= 1
    for i in range(len(rowTricks)):
        while rowTricks[i] > 0: Math.Max(i + 3, i + 3)
