def calculate_cost(N, C, M):
    models = []

    for _ in range(M):
        U, V = map(int, input().split())
        models.append((U, V))

    results = []

    for N in range(1, N+1):
        total_cost = 0
        total_time_penalty = 0

        for model in models:
            if model[0] > N or model[1] > N or model[0] == model[1]:
                continue

            distances = []

            for i in range(N):
                current_flight_count = 0

                for j in range(N):
                    if i != j and j >= model[0]-1 and j <= model[1]-1:
                        distances.append(abs(N - i) + abs(N - j))
                        current_flight_count += 1

            distance_sum = sum(distances) / current_flight_count

            time_penalty = sum([min(distance, 2*C) for distance in distances])

            total_cost += N - model[0] + N - model[1] + C * current_flight_count
            total_time_penalty += time_penalty

        results.append(total_cost + total_time_penalty)

    return min(results)

