from math import gcd

def is_awkward(l, r):
    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    min_iq = min(l, r)
    max_iq = max(l, r)

    awkward_pairs_count = 0

    for i in range(2, max_iq + 1):
        if gcd(digit_sum(i), digit_sum(max_iq - i)) == 1:
            awkward_pairs_count += 1

    for i in range(2, min_iq):
        if gcd(digit_sum(i), digit_sum(l)) == 1 and gcd(digit_sum(i), digit_sum(r)) == 1:
            awkward_pairs_count += 1

    return awkward_pairs_count

T = int(input())
results = []

for _ in range(T):
    L, R = map(int, input().split())
    results.append(is_awkward(L, R) % (10**9 + 7))

